#include <iostream>

template <class T>
int binsearch(const T array[], int low, int high, T value) {
    while (low <= high) {
        auto mid = low + (high - low) / 2;
        if (value < array[mid]) {
            high = mid - 1;
        } else if (value > array[mid]) {
            low = mid + 1;
        } else {
            return mid;
        }
    }
    return -1;
}

int main() {
    int array[] = {2, 3, 5, 6, 8};
    int result1 = binsearch(array, 0, sizeof(array)/sizeof(int), 4),
        result2 = binsearch(array, 0, sizeof(array)/sizeof(int), 8);
    if (result1 == -1) std::cout << "4 not found!" << std::endl;
    else std::cout << "4 found at " << result1 << std::endl;
    if (result2 == -1) std::cout << "8 not found!" << std::endl;
    else std::cout << "8 found at " << result2 << std::endl;

    return 0;
}

#include <iostream>
#include <string>

std::string caesarCipher(const std::string& text, int shift) {
    std::string result = text;
    for (char& c : result) {
        if (isalpha(c)) {
            char base = islower(c) ? 'a' : 'A';
            c = (c - base + shift) % 26 + base;
        }
    }
    return result;
}

