import (
	"fmt"
	"strings"
)

type ckey struct {
	enc, dec func(rune) rune
}

func newCaesar(k int) (*ckey, bool) {
	if k < 1 || k > 25 {
		return nil, false
	}
	rk := rune(k)
	return &ckey{
		enc: func(c rune) rune {
			switch {
			case c >= 'a' && c <= 'z'-rk:
				return c + rk
			case c > 'z'-rk && c <= 'z':
				return c + rk - 26
			case c >= 'A' && c <= 'Z'-rk:
				return c + rk
			case c > 'Z'-rk && c <= 'Z':
				return c + rk - 26
			default:
				return c
			}
		},
		dec: func(c rune) rune {
			switch {
			case c >= 'a'+rk && c <= 'z':
				return c - rk
			case c >= 'A'+rk && c <= 'Z':
				return c - rk
			case c < 'a'+rk && c >= 'a':
				return c - rk + 26
			case c < 'A'+rk && c >= 'A':
				return c - rk + 26
			default:
				return c
			}
		},
	}, true
}

func (ck *ckey) encipher(pt string) string {
	if ck == nil {
		return ""
	}
	return strings.Map(ck.enc, pt)
}

func (ck *ckey) decipher(ct string) string {
	if ck == nil {
		return ""
	}
	return strings.Map(ck.dec, ct)
}

func main() {
	pt := "The five boxing wizards jump quickly"
	fmt.Println("Plaintext:", pt)
	for _, key := range []int{0, 1, 7, 25, 26} {
		ck, ok := newCaesar(key)
		if !ok {
			fmt.Println("Key", key, "invalid")
			continue
		}
		ct := ck.encipher(pt)
		fmt.Println("Key", key)
		fmt.Println("  Enciphered:", ct)
		fmt.Println("  Deciphered:", ck.decipher(ct))
	}
}

