import java.lang.Math;

public class FastEntropy {

    public static double getShannonEntropy(String s) {
        int n = s.length();
        if (n == 0) return 0.0;

        int[] count = new int[256];
        for (int i = 0; i < n; ++i) {
            count[s.charAt(i)]++;
        }

        double e = 0.0;
        for (int c : count) {
            if (c == 0) continue;
            double p = (double) c / n;
            e += p * log2(p);
        }
        return -e;
    }

    private static double log2(double a) {
        return Math.log(a) / Math.log(2);
    }

    public static void main(String[] args) {
        String[] sstr = {
            "1223334444",
            "1223334444555555555", 
            "122333", 
            "1227774444",
            "aaBBcccDDDD",
            "1234567890abcdefghijklmnopqrstuvwxyz",
            "Rosetta Code",
        };

        for (String ss : sstr) {
            double entropy = FastEntropy.getShannonEntropy(ss);
            System.out.printf("Shannon entropy of %40s: %.12f%n", "\"" + ss + "\"", entropy);
        }
    }
}

