fun facti(n: Int): Long {
    require(n >= 0) { "negative numbers not allowed" }
    return (1..n).fold(1L) { acc, i -> acc * i }
}

fun factr(n: Int): Long {
    require(n >= 0) { "negative numbers not allowed" }
    return if (n < 2) 1L else n * factr(n - 1)
}

fun main() {
    val n = 20
    println("$n! = ${facti(n)}")
