function binary_search($array, $secret) {
    $start = 0;
    $end = count($array) - 1;

    while ($start <= $end) {
        $guess = (int)(($start + $end) / 2);

        if ($array[$guess] === $secret) {
            return $guess;
        }

        if ($array[$guess] > $secret) {
            $end = $guess - 1;
        } else {
            $start = $guess + 1;
        }
    }

    return -1;
}

