export class InputHandler {
  private dataStore: { state: number; events: { type: 'start' | 'pause' | 'resume' | 'stop'; timestamp: number }[] };

  constructor(dataStore: { state: number; events: { type: 'start' | 'pause' | 'resume' | 'stop'; timestamp: number }[] }) {
    this.dataStore = dataStore;
  }

  handleInput(event: { type: 'start' | 'pause' | 'resume' | 'stop'; userId: string; status?: string }): void {
    try {
      const currentEvent = { ...event };

      switch (currentEvent.type) {
        case 'start':
          this.startPomodoro(currentEvent);
          break;
        case 'pause':
          this.pausePomodoro(currentEvent);
          break;
        case 'resume':
          this.resumePomodoro(currentEvent);
          break;
        case 'stop':
          this.stopPomodoro(currentEvent);
          break;
        default:
