using System;
using System.Collections.Generic;

List<long> fib(int n)
{
    var values = new List<long>();
    long a = 0;
    long b = 1;
    for (int i = 0; i < n; i++)
    {
        values.Add(a);
        long next = a + b;
        a = b;
        b = next;
    }
    return values;
}

Console.WriteLine(string.Join(" ", fib(5)));

using System;
using System.Collections.Generic;

bool isPrime(int value)
{
    if (value < 2)
    {
        return false;
    }
    for (int p = 2; p * p <= value; p++)
    {
        if (value % p == 0)
        {
            return false;
        }
    }
    return true;
}

var found = new List<int>();
for (int value = 2; value <= 5; value++)
{
    if (isPrime(value))
    {
        found.Add(value);
    }
}
Console.WriteLine(string.Join(",", found));

