fn bubble(values: &[i64]) -> Vec<i64> {
    let mut items = values.to_vec();
    for i in 0..items.len() {
        for j in 0..items.len().saturating_sub(1 + i) {
            if items[j] > items[j + 1] {
                items.swap(j, j + 1);
            }
        }
    }
    items
}

