    int numbers[COUNT] = {6, 11, 12, 7, 11, 13, 17, 19};
    int parts[MAX_PARTS];
    for (int i = 0; i < COUNT; i++) {
        int found = factorise(numbers[i], parts);
        printf("%d: ", numbers[i]);
        render(parts, found);
        printf("\n");
    }
    return 0;
}

