const VALUES = [3, 1, 4];

class Node {
  constructor(value, next) {
    this.value = value;
    this.next = next || null;
  }
}

function build(values) {
  let head = null;
  for (let index = values.length - 1; index >= 0; index -= 1) {
    head = new Node(values[index], head);
  }
  return head;
}

function reverse(head) {
