STOCK = [('bolt', 12, 0.5), ('nut', 40, 0.1), ('washer', 0, 0.05)]

def available(stock):
    return [row for row in stock if row[1] > 0]

def value(rows):
    return sum(qty * price for _, qty, price in rows)

def lines(rows):
    out = []
    for name, qty, price in rows:
        out.append(f'{name:<8} {qty:>3} x {price:>6.2f} = {qty * price:>8.2f}')
    return out

rows = available(STOCK)
print('\n'.join(lines(rows)))
print(f'total {value(rows):.2f}')

ROWS = [('bolt', 12, 0.5), ('nut', 40, 0.1), ('washer', 0, 0.05)]

def by_value(rows):
    return sorted(rows, key=lambda row: (-row[1] * row[2], row[0]))

def by_name(rows):
    return sorted(rows, key=lambda row: row[0])

def render(rows):
    return ', '.join(f'{name}({qty})' for name, qty, _ in rows)

def total_value(rows):
    return sum(qty * price for _, qty, price in rows)

print('value', render(by_value(ROWS)))
print('name ', render(by_name(ROWS)))
print('total', total_value(ROWS))

