class Account:
    def __init__(self, opening):
        self.balance = opening
        self.log = []

    def deposit(self, amount):
        self.balance += amount
        self.log.append(('deposit', amount, self.balance))

    def withdraw(self, amount):
        if amount > self.balance:
            self.log.append(('refused', amount, self.balance))
            return False
        self.balance -= amount
        self.log.append(('withdraw', amount, self.balance))
        return True

