def tokens(text)
  text.split
end

def counts(words)
  table = Hash.new(0)
  words.each { |word| table[word] += 1 }
  table
end

def ranked(table)
  table.sort_by { |word, count| [-count, word] }.map { |word, _| word }
end

table = counts(tokens(TEXT))
ranked(table).first(4).each { |word| puts format('%s: %d', word, table[word]) }

