def available(stock)
  stock.select { |row| row[1] > 0 }
end

def total(rows)
  rows.sum { |row| row[1] * row[2] }
end

def report(rows)
  rows.map { |name, qty, price| format('%-8s %3d x %6.2f = %8.2f', name, qty, price, qty * price) }
end

rows = available(STOCK)
puts report(rows).join("\n")
puts format('total %.2f', total(rows))

