    items.iter().map(|item| item.qty as f64 * item.price).sum()
}

fn render(items: &[&Item]) -> Vec<String> {
    items
        .iter()
        .map(|item| {
            format!(
                "{:<8} {:>3} x {:>6.2} = {:>8.2}",
                item.name,
                item.qty,
                item.price,
                item.qty as f64 * item.price
