fn factorise(mut value: i32) -> Vec<i32> {
    let mut out = Vec::new();
    let mut divisor = 2;
    while divisor * divisor <= value {
        while value % divisor == 0 {
            out.push(divisor);
            value /= divisor;
        }
        divisor += 1;
    }
    if value > 1 {
        out.push(value);
    }
    out
}

fn render(parts: &[i32]) -> String {
    parts
        .iter()
        .map(|part| part.to_string())
        .collect::<Vec<String>>()
        .join(" x ")
}

fn main() {
    let numbers: Vec<i32> = vec![6, 11, 12, 7, 11, 13, 17, 19];
    for number in numbers {
        println!("{}: {}", number, render(&factorise(number)));
    }
}

