final class Node {
    var value: Int
    var next: Node?

    init(_ value: Int, _ next: Node? = nil) {
        self.value = value
        self.next = next
    }
}

func build(_ values: [Int]) -> Node? {
    var head: Node? = nil
    for value in values.reversed() {
        head = Node(value, head)
    }
    return head
}

func reverse(_ head: Node?) -> Node? {
