--- scanner.js ---
import fs from 'fs';
import path from 'path';
import crypto from 'crypto';

async function findDuplicates(root) {
  const duplicates = {};
  let totalFiles = 0;

  function walk(dir) {
    for (const entry of fs.readdirSync(dir)) {
      const fullPath = path.join(dir, entry);
      if (fs.statSync(fullPath).isDirectory()) {
        walk(fullPath);
      } else {
        totalFiles += 1;
        const hash = crypto.createHash('sha256').update(fs.readFileSync(fullPath)).digest('hex');
        duplicates[hash] = duplicates[hash] || [];
        duplicates[hash].push(fullPath);
      }
    }
  }

  walk(root);

  let foundDupe = false;
  for (const hash in duplicates) {
    if (duplicates[hash].length > 1) {
      const size = fs.statSync(duplicates[hash][0]).size;
      console.log(`DUPLICATE ${size}: ${duplicates[hash].join(', ')}`);
      foundDupe = true;
    }
  }

  if (!foundDupe) {
    console.error('NO_DUPLICATES');
  }
}

