class ExpenseItem:
    category: str
    amount: float
    description: str

def addExpense(e: ExpenseItem) -> None:
    try:
        with open("expenses.json", "r") as f:
            expenses = json.load(f)
    except FileNotFoundError:
        expenses = []
    expenses.append({
        "category": e.category,
        "amount": e.amount,
        "description": e.description
    })
    with open("expenses.json", "w") as f:
        json.dump(expenses, f)

def listExpenses() -> list[ExpenseItem]:
    try:
        with open("expenses.json", "r") as f:
